t = int(input())
n = 1001
l = [[0 for i in range(n)] for i in range(n)]
for i in range(1, n):
	l[i][1] = i * (i + 1) // 2
for j in range(1, n):
	for k in range(2, n):
		l[j][k] = l[j][k - 1] + (k - 1) + (j - 1)
for z in range(t):
	(r1, c1, r2, c2) = list(map(int, input().split()))
	s = 0
	for a in range(r1, r2 + 1):
		s += l[a][c1]
	for b in range(c1 + 1, c2 + 1):
		s += l[r2][b]
	print(s)
